def findAllConcatenatedWordsInADict(words: list[str]) -> list[str]:
    word_set = set(words)
    memo = {}
    def can_form(w):
        if w in memo: return memo[w]
        for i in range(1, len(w)):
            prefix = w[:i]
            suffix = w[i:]
            if prefix in word_set:
                if suffix in word_set or can_form(suffix):
                    memo[w] = True
                    return True
        memo[w] = False
        return False
    res = [w for w in words if can_form(w)]
    return sorted(res)

